-- Complementa fatores publicados que ficaram nulos por falta de coincidência na fatura.
-- Fonte: docs/faturamento-celulas-pdf.json (hash, página e posição), cruzada com raw/layout.
-- Não modifica fatores originais já preenchidos nem acertos vigentes do administrador.
create temporary table neo_fat_pdf(tabela text,codigo text,csc numeric,cod numeric,origem text,primary key(tabela,codigo)) on commit drop;
lock table public.neo_fat_contrato in share row exclusive mode;
create temporary table neo_fat_pdf_antes on commit drop as
select c.* from public.neo_fat_contrato c join neo_fat_pdf p using(tabela,codigo)
where c.fator_original is null or c.fator_cod_original is null;
-- Exceção exclusivamente nesta transação de carga inicial dos originais ausentes.
-- A trilha é escrita abaixo; a imutabilidade continua ativa após a migration.
alter table public.neo_fat_contrato disable trigger neo_fat_log;
update public.neo_fat_contrato c set
 fator_original=coalesce(c.fator_original,p.csc),fator_cod_original=coalesce(c.fator_cod_original,p.cod),
 fator_csc=coalesce(c.fator_csc,p.csc),fator_cod=coalesce(c.fator_cod,p.cod),
 validado=true,origem=p.origem,atualizado_em=now()
from neo_fat_pdf p where c.tabela=p.tabela and c.codigo=p.codigo
and (c.fator_original is null or c.fator_cod_original is null);
select c.tabela,c.codigo,to_jsonb(a),to_jsonb(c),
 'Carga dos fatores publicados no PDF: células e texto conferidos, independentemente de coincidência na fatura 9844. Migration 020.'
from neo_fat_pdf_antes a join public.neo_fat_contrato c using(tabela,codigo);
alter table public.neo_fat_contrato enable trigger neo_fat_log;
